/**
 * Html.java
 * Builds the HTML (page layout, styling, escaping) for the web version.
 * All pages are generated by Java code, so the whole project is written in Java.
 */
public class Html {

    private static final String CSS =
        "*{box-sizing:border-box}"
      + "body{margin:0;font-family:Segoe UI,Roboto,Arial,sans-serif;background:#f3f5fb;color:#222}"
      + "header{background:linear-gradient(135deg,#27368f,#4a63d6);color:#fff;padding:18px 16px;text-align:center}"
      + "header h1{margin:0;font-size:1.35rem}header p{margin:4px 0 0;font-size:.85rem;opacity:.9}"
      + "nav{background:#1d2a73;display:flex;flex-wrap:wrap;justify-content:center}"
      + "nav a{color:#fff;text-decoration:none;padding:11px 14px;font-size:.92rem}"
      + "nav a:hover{background:#3b4fc0}"
      + "main{max-width:900px;margin:18px auto;padding:0 12px}"
      + ".card{background:#fff;border-radius:10px;padding:18px;margin-bottom:16px;box-shadow:0 2px 8px rgba(0,0,0,.08)}"
      + ".card h2{margin-top:0;color:#27368f;font-size:1.2rem}.card h3{margin:0 0 8px;color:#27368f}"
      + "label{display:block;margin:12px 0 4px;font-weight:600;font-size:.92rem}"
      + "input,select{width:100%;padding:10px;border:1px solid #b8c0e0;border-radius:6px;font-size:1rem}"
      + "button,.btn{display:inline-block;background:#27368f;color:#fff;border:0;border-radius:6px;padding:10px 18px;"
      + "font-size:1rem;cursor:pointer;text-decoration:none;margin-top:14px}"
      + "button:hover,.btn:hover{background:#3b4fc0}.ghost{background:#fff;color:#27368f;border:1px solid #27368f}"
      + ".hint{font-size:.82rem;color:#666;margin:4px 0 0}"
      + "table{width:100%;border-collapse:collapse;font-size:.92rem}"
      + "th,td{border:1px solid #d5daf0;padding:7px 8px;text-align:left}th{background:#e8ecfb}"
      + ".wrap{overflow-x:auto}td.n,th.n{text-align:center}"
      + ".pass{color:#0a8a3a;font-weight:700}.fail{color:#c62828;font-weight:700}"
      + ".stats{display:flex;gap:10px;flex-wrap:wrap}.stat{flex:1;min-width:120px;background:#e8ecfb;border-radius:8px;padding:12px;text-align:center}"
      + ".stat b{display:block;font-size:1.5rem;color:#27368f}"
      + ".err{background:#fdecea;border-left:5px solid #c62828}"
      + "footer{text-align:center;font-size:.78rem;color:#666;padding:14px}";

    // Escapes special characters so text can be shown safely inside HTML
    public static String esc(String s) {
        if (s == null) return "";
        return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
                .replace("\"", "&quot;").replace("'", "&#39;");
    }

    // Wraps the given content in the common page layout (header, menu, footer)
    public static String page(String title, String content) {
        StringBuilder sb = new StringBuilder();
        sb.append("<!DOCTYPE html><html lang='en'><head><meta charset='UTF-8'>");
        sb.append("<meta name='viewport' content='width=device-width, initial-scale=1'>");
        sb.append("<title>").append(esc(title)).append(" - Student Result Management System</title>");
        sb.append("<style>").append(CSS).append("</style></head><body>");
        sb.append("<header><h1>Student Result Management System</h1>");
        sb.append("<p>Semester-wise results &middot; B.Tech CSE &middot; Object Oriented Programming (Java)</p></header>");
        sb.append("<nav><a href='/'>Home</a><a href='/add'>Add Result</a><a href='/search'>Search</a>");
        sb.append("<a href='/all'>All Results</a><a href='/summary'>Class Summary</a></nav>");
        sb.append("<main>").append(content).append("</main>");
        sb.append("<footer>OOP Mini Project (PCC-CS503) &middot; Budge Budge Institute of Technology</footer>");
        sb.append("</body></html>");
        return sb.toString();
    }

    // A red message card with a link to go back
    public static String error(String message, String backHref) {
        return page("Error", "<div class='card err'><h2>Error</h2><p>" + esc(message) + "</p>"
                + "<a class='btn ghost' href='" + backHref + "'>Go back</a></div>");
    }
}
